import androidx.compose.foundation.layout.Arrangement import androidx.compose.foundation.layout.PaddingValues import androidx.compose.foundation.layout.Row import androidx.compose.foundation.layout.fillMaxSize import androidx.compose.foundation.layout.fillMaxWidth import androidx.compose.foundation.layout.padding import androidx.compose.foundation.layout.size import androidx.compose.foundation.lazy.LazyColumn import androidx.compose.foundation.lazy.items import androidx.compose.material3.Card import androidx.compose.material3.CardDefaults import androidx.compose.material3.ExperimentalMaterial3Api import androidx.compose.material3.Icon import androidx.compose.material3.MaterialTheme import androidx.compose.material3.Scaffold import androidx.compose.material3.Text import androidx.compose.material3.TopAppBar import androidx.compose.runtime.Composable import androidx.compose.ui.Alignment import androidx.compose.ui.Modifier import androidx.compose.ui.text.font.FontWeight import androidx.compose.ui.unit.dp import com.thestudypath.pdfviewer.navigation.AppDestination
private data class ToolDefinition( val id: String, val title: String, val description: String, val category: String, val icon: ImageVector, val selectionMode: DocumentSelectionMode?, val status: String, )
private val toolDefinitions = listOf( ToolDefinition( id = "compress", title = "Compress PDF", description = "Reduce the file size of your PDF documents.", category = "Tools", icon = Icons.Default.Compress, selectionMode = DocumentSelectionMode.Single, status = "Available", ), ToolDefinition( id = "images_to_pdf", title = "Images to PDF", description = "Convert images to a single PDF document.", category = "Tools", icon = Icons.Default.PictureAsPdf, selectionMode = DocumentSelectionMode.Single, status = "Available", ), ToolDefinition( id = "extract_text", title = "Extract Text", description = "Extract text content from PDF documents.", category = "Tools", icon = Icons.AutoMirrored.Filled.TextSnippet, selectionMode = DocumentSelectionMode.Single, status = "Available", ), ToolDefinition( id = "split", title = "Split PDF", description = "Split a PDF document into multiple parts.", category = "Tools", icon = Icons.Default.ArrowForward, selectionMode = DocumentSelectionMode.Single, status = "Available", ), ToolDefinition( id = "merge", title = "Merge PDFs", description = "Merge multiple PDF documents into a single file.", category = "Tools", icon = Icons.Default.MergeType, selectionMode = DocumentSelectionMode.Multiple, status = "Available", ), )
@OptIn(ExperimentalMaterial3Api::class) @Composable fun ToolsRoute( onOpenTool: (String) -> Unit, ) { Scaffold( topBar = { TopAppBar(title = { Text(AppDestination.Tools.label) }) }, ) { innerPadding -> LazyColumn( modifier = Modifier .fillMaxSize() .padding(innerPadding), contentPadding = PaddingValues(16.dp), verticalArrangement = Arrangement.spacedBy(12.dp), ) { items(toolDefinitions, key = { it.id }) { tool -> ToolListItem( tool = tool, onClick = { onOpenTool(tool.id) }, ) } } } }
@Composable private fun ToolListItem( tool: ToolDefinition, onClick: () -> Unit, ) { Card( onClick = onClick, modifier = Modifier.fillMaxWidth(), colors = CardDefaults.cardColors( containerColor = MaterialTheme.colorScheme.surfaceContainerLow, ), ) { Row( modifier = Modifier .fillMaxWidth() .padding(horizontal = 16.dp, vertical = 18.dp), horizontalArrangement = Arrangement.spacedBy(16.dp), verticalAlignment = Alignment.CenterVertically, ) { Icon( imageVector = tool.icon, contentDescription = tool.title, modifier = Modifier.size(24.dp), tint = MaterialTheme.colorScheme.primary, ) Text( text = tool.title, style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.SemiBold, ) } } }

